Sure, I'd be happy to help you create a simple to-do list program. Here's a Python program that meets your requirements. This program uses a simple list to store the tasks and allows the user to interact with it using the `add`, `remove`, and `view` commands.

```python
# Initialize an empty to-do list
to_do_list = []

def add_task():
    """Add a task to the to-do list."""
    task = input("Enter a task to add (or type 'done' to complete a task): ")

    if task.lower() == "done":
        # Remove the last task if it's 'done'
        if to_do_list:
            to_do_list.pop()
        return

    to_do_list.append(task)
    print(f"Added: {task}")

def remove_task():
    """Remove a task from the to-do list."""
    if not to_do_list:
        print("The to-do list is empty.")
        return

    index = 0
    for task in to_do_list:
        print(f"{index + 1}. {task}")
        index += 1

    try:
        task_index = int(input("Enter the index of the task to remove: ")) - 1
    except ValueError:
        print("Invalid input. Please enter a number.")
        return

    if task_index < len(to_do_list):
        to_do_list.pop(task_index)
        print(f"Removed task: {to_do_list[task_index]}")
    else:
        print("No task found at that index.")

def view_tasks():
    """View the current to-do list."""
    if not to_do_list:
        print("The to-do list is empty.")
        return

    index = 0
    for task in to_do_list:
        print(f"{index + 1}. {task}")
        index += 1


def main():
    while True:
        command = input("\nEnter a command (add, remove, view, or quit): ").lower()

        if command == "add":
            add_task()
        elif command == "remove":
            remove_task()
        elif command == "view":
            view_tasks()
        elif command == "quit":
            print("Goodbye!")
            break
        else:
            print("Invalid command. Please try again.")


if __name__ == "__main__":
    main()
```

This program allows the user to interact with the to-do list using the `add`, `remove`, and `view` commands. The user can also complete a task by typing "done" instead of adding a new task.
